// ─── Tests ────────────────────────────────────────────────────────────────────
// Do not edit this file.

package mergeintervals

import (
	"reflect"
	"testing"
)

func eq(a, b [][]int) bool {
	if len(a) == 0 && len(b) == 0 {
		return true
	}
	return reflect.DeepEqual(a, b)
}

func TestEmpty(t *testing.T) {
	if got := MergeIntervals([][]int{}); !eq(got, [][]int{}) {
		t.Fatalf("got %v", got)
	}
}

func TestSingle(t *testing.T) {
	if got := MergeIntervals([][]int{{1, 4}}); !eq(got, [][]int{{1, 4}}) {
		t.Fatalf("got %v", got)
	}
}

func TestClassic(t *testing.T) {
	got := MergeIntervals([][]int{{1, 3}, {2, 6}, {8, 10}, {15, 18}})
	want := [][]int{{1, 6}, {8, 10}, {15, 18}}
	if !eq(got, want) {
		t.Fatalf("got %v, want %v", got, want)
	}
}

func TestTouching(t *testing.T) {
	got := MergeIntervals([][]int{{1, 4}, {4, 5}})
	want := [][]int{{1, 5}}
	if !eq(got, want) {
		t.Fatalf("got %v, want %v", got, want)
	}
}

func TestDisjoint(t *testing.T) {
	got := MergeIntervals([][]int{{1, 2}, {3, 4}, {5, 6}})
	want := [][]int{{1, 2}, {3, 4}, {5, 6}}
	if !eq(got, want) {
		t.Fatalf("got %v, want %v", got, want)
	}
}

func TestUnsorted(t *testing.T) {
	got := MergeIntervals([][]int{{15, 18}, {1, 3}, {8, 10}, {2, 6}})
	want := [][]int{{1, 6}, {8, 10}, {15, 18}}
	if !eq(got, want) {
		t.Fatalf("got %v, want %v", got, want)
	}
}

func TestAllOverlap(t *testing.T) {
	got := MergeIntervals([][]int{{1, 4}, {2, 3}, {3, 5}})
	want := [][]int{{1, 5}}
	if !eq(got, want) {
		t.Fatalf("got %v, want %v", got, want)
	}
}
